import{at as e,it as t,t as n,yt as r}from"./chunks/framework.CgPcrqpH.js";var i=JSON.parse(`{"title":"Upgrading","description":"Find the permanent, versioned upgrade guides, which one fits the ember-data or WarpDrive version your app is on, and where deprecation guides currently live.","frontmatter":{"title":"Upgrading","description":"Find the permanent, versioned upgrade guides, which one fits the ember-data or WarpDrive version your app is on, and where deprecation guides currently live."},"headers":[],"relativePath":"upgrading/index.md","filePath":"upgrading/index.md"}`),a={name:`upgrading/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="upgrading-warpdrive" tabindex="-1">Upgrading <strong><em>Warp</em>Drive</strong> <a class="header-anchor" href="#upgrading-warpdrive" aria-label="Permalink to “Upgrading WarpDrive”">​</a></h1><p>This section is the permanent home for point-in-time content: major-version upgrade guides, deprecation guidance, and one-off feature migrations. Unlike the rest of the guides — which describe the <em>current</em> API and change version to version — pages here describe how to get from one specific point to another, and are expected to keep working the same way for whoever finds them years from now.</p><h2 id="guarantees" tabindex="-1">Guarantees <a class="header-anchor" href="#guarantees" aria-label="Permalink to “Guarantees”">​</a></h2><ul><li><strong>URLs are permanent.</strong> A page&#39;s URL is never renamed and never unpublished. If a page&#39;s content is fully superseded, the page is kept in place, marked as superseded, and links forward to its replacement rather than being deleted.</li><li><strong>Pages are dated and versioned.</strong> Every page under <code>Upgrading</code> records the <strong><em>Warp</em>Drive</strong>* version (and, where useful, the date) it was authored against, usually with a <code>&lt;SinceBadge /&gt;</code> near the top of the page.</li><li><strong>Content is organized by major version.</strong> Each major version gets its own sub-section (e.g. <a href="/pr-preview/pr-9539/upgrading/v5/">4.x → 5.x</a>) containing that version&#39;s upgrade guide plus any deprecation or feature-specific migration guides written for it. The one exception is <a href="/pr-preview/pr-9539/upgrading/ember-data/">ember-data → WarpDrive</a>, for apps that start from <code>ember-data</code> packages alone.</li></ul><p>See <a href="/pr-preview/pr-9539/guides/contributing/writing-documentation/writing-guides#upgrading-and-blog-pages">Upgrading and Blog Pages</a> for the authoring rules that keep these guarantees true.</p><h2 id="which-guide-do-i-need" tabindex="-1">Which Guide Do I Need? <a class="header-anchor" href="#which-guide-do-i-need" aria-label="Permalink to “Which Guide Do I Need?”">​</a></h2><p>Check which <code>ember-data</code> version your app is on.</p><ul><li><strong>4.12 or earlier.</strong> These releases publish only <code>ember-data</code> and <code>@ember-data/*</code> packages. Start at <a href="/pr-preview/pr-9539/upgrading/ember-data/">ember-data → WarpDrive</a>. It runs the latest WarpDrive beside your current <code>ember-data</code> and moves one route at a time. To stay on 4.12 and adopt the new request APIs in the store you already have, see <a href="/pr-preview/pr-9539/upgrading/ember-data/incremental-adoption">Adopting the Request APIs on 4.12</a>.</li><li><strong>4.13 or any 5.x.</strong> These releases already depend on <code>@warp-drive/*</code> packages. Start at <a href="/pr-preview/pr-9539/upgrading/v5/">4.x → 5.x</a>, which uses <a href="/pr-preview/pr-9539/upgrading/v5/two-store-migration#mirror-versions">mirror packages</a> to run both versions side by side.</li></ul><h2 id="deprecations" tabindex="-1">Deprecations <a class="header-anchor" href="#deprecations" aria-label="Permalink to “Deprecations”">​</a></h2><p>Individual deprecation IDs and their descriptions ship as part of the <a href="/pr-preview/pr-9539/api/@warp-drive/core/build-config/deprecations/">Deprecations API docs</a>. Longer-form deprecation guides for EmberData/WarpDrive currently live at <a href="https://deprecations.emberjs.com/" target="_blank" rel="noreferrer">deprecations.emberjs.com</a> and are planned to move under this section — see <a href="https://github.com/warp-drive-data/warp-drive/issues/11028" target="_blank" rel="noreferrer">issue #11028</a> for status.</p>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};